// Positioning, expressed as a typed offer rather than a vibe.
// The shape itself communicates: bounded scope, named outcome, anchored price.
type Offer = {
  name: string;          // "Salon System", not "custom booking site"
  forWho: string;        // the niche it self-qualifies
  outcome: string;       // what changes for the client
  includes: string[];    // scope, pre-answered
  startingAt: number;    // an anchor, so nobody opens with "send a quote"
  trialDays: number;     // remove the risk that stalls the yes
};

const salon: Offer = {
  name: "Supreme Suite — Salon",
  forWho: "salons & barbershops ready to take bookings online",
  outcome: "clients book and pay themselves, 24/7",
  includes: ["CRM", "branded website", "AI staff", "online payments"],
  startingAt: 0,         // starts on a free trial, not a negotiation
  trialDays: 3,
};
